Matrix features = Matrix.fromRows(new double[][] {
    {0.0, 0.0}, {0.3, 0.1}, {0.1, 0.4},
    {5.0, 5.0}, {5.2, 4.8}, {4.9, 5.3},
    {9.0, 0.5}
});
DBSCAN dbscan = DBSCAN.builder()
        .eps(0.6)
        .minPoints(3)
        .metric(DistanceMetric.EUCLIDEAN)
        .build()
        .fit(features, null);
int[] labels = dbscan.labels();
int clusters = dbscan.clusterCount();
int noise = dbscan.noiseCount();

Matrix features = Matrix.fromRows(new double[][] {
    {1.0, 2.0}, {1.2, 1.8}, {0.9, 2.1},
    {5.0, 8.0}, {5.4, 7.6}, {4.8, 8.2}
});
double[] targets = {0.0, 0.0, 0.0, 1.0, 1.0, 1.0};
GaussianNaiveBayes model = GaussianNaiveBayes.builder()
        .varianceSmoothing(1e-9)
        .build()
        .fit(features, targets);
double[] predicted = model.predict(features);
Matrix logPosterior = model.predictLogProbability(features);
Matrix posterior = model.predictProbability(features);

Matrix features = Matrix.fromRows(new double[][] {
    {0.0, 0.0}, {0.4, 0.2}, {0.1, 0.5},
    {9.6, 9.8}, {10.0, 10.2}, {9.4, 9.9}
});
KMeans kmeans = KMeans.builder()
        .clusters(2)
        .restarts(4)
        .maxIterations(200)
        .seed(7L)
        .build()
        .fit(features);
double[] assignment = kmeans.predict(features);
double[] distance = kmeans.transform(features);
Matrix centers = kmeans.centroids();
double inertia = kmeans.inertia();

Matrix features = Matrix.fromRows(new double[][] {
    {2.5, 2.4}, {0.5, 0.7}, {2.2, 2.9},
    {1.9, 2.2}, {3.1, 3.0}, {2.3, 2.7}
});
PCA pca = PCA.builder()
        .components(1)
        .solver(EigenSolver.AUTO)
        .whiten(true)
        .build()
        .fit(features);
Matrix projected = pca.transform(features);
Matrix restored = pca.inverseTransform(projected);
double[] ratio = pca.explainedVarianceRatio();
